import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"Telegram","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/channels/telegram.md","filePath":"ja/integrations/channels/telegram.md","lastUpdated":1792323081000}'),l={name:"ja/integrations/channels/telegram.md"};function n(i,e,h,s,d,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h1><p>Memoh Bot を Telegram につなぎます。Memoh の Telegram 対応は比較的充実しており、ストリーミング、Markdown、添付ファイルなどをサポートします。</p><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>Telegram アカウント。<strong>@BotFather</strong> と対話して Bot を作成するために使います。</li><li>Memoh Bot。チャネルはその <strong>プラットフォーム</strong> タブで設定します。</li></ul><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-telegram-で-botfather-を使って-bot-を作成する" tabindex="-1">1. Telegram で @BotFather を使って Bot を作成する <a class="header-anchor" href="#_1-telegram-で-botfather-を使って-bot-を作成する" aria-label="Permalink to &quot;1. Telegram で @BotFather を使って Bot を作成する&quot;">​</a></h3><ol><li>Telegram で公式の <strong>@BotFather</strong> を検索します。</li><li><code>/newbot</code> を送信します。</li><li>プロンプトに従って入力します。 <ul><li><strong>Name</strong>：表示名。例：<code>My Memoh Bot</code>。</li><li><strong>Username</strong>：グローバルに一意で、<code>bot</code> で終わる名前。例：<code>my_memoh_bot</code>。</li></ul></li><li>BotFather が <strong>API Token</strong>（<code>123456789:ABC...</code> のような形式）を返します。<strong>漏えいさせないでください。</strong></li></ol><blockquote><p>公式ガイド：<a href="https://core.telegram.org/bots/tutorial" target="_blank" rel="noreferrer">Telegram Bot Tutorial</a></p></blockquote><h3 id="_2-memoh-で-telegram-チャネルを追加する" tabindex="-1">2. Memoh で Telegram チャネルを追加する <a class="header-anchor" href="#_2-memoh-で-telegram-チャネルを追加する" aria-label="Permalink to &quot;2. Memoh で Telegram チャネルを追加する&quot;">​</a></h3><ol><li>Bot の詳細ページを開き、<strong>プラットフォーム</strong> タブに移動します。</li><li><strong>Add Channel</strong> をクリックし、<strong>Telegram</strong> を選択します。</li><li><strong>API Token</strong> を認証情報フィールドに入力します。</li><li><strong>Save and Enable</strong> をクリックします。</li></ol><h2 id="認証情報" tabindex="-1">認証情報 <a class="header-anchor" href="#認証情報" aria-label="Permalink to &quot;認証情報&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th></tr></thead><tbody><tr><td><strong>API Token</strong></td><td>Bot 作成時に BotFather から送られる token（<code>123456789:ABC...</code> のような形式）。漏えいさせないでください。</td></tr></tbody></table><h2 id="動作確認" tabindex="-1">動作確認 <a class="header-anchor" href="#動作確認" aria-label="Permalink to &quot;動作確認&quot;">​</a></h2><p>Telegram で Bot とのプライベートチャットを開き、<code>/help</code> を送信します。Bot がコマンド一覧を返せば、チャネルは機能しています。</p><h2 id="グループチャット" tabindex="-1">グループチャット <a class="header-anchor" href="#グループチャット" aria-label="Permalink to &quot;グループチャット&quot;">​</a></h2><p>Telegram はグループチャットに対応しています。Bot をグループに追加したあと、ユーザー名で @メンションするとグループ内で会話できます。</p><h2 id="無効化と認証情報の更新" tabindex="-1">無効化と認証情報の更新 <a class="header-anchor" href="#無効化と認証情報の更新" aria-label="Permalink to &quot;無効化と認証情報の更新&quot;">​</a></h2><p>Bot の <strong>プラットフォーム</strong> タブから、いつでもこのチャネルを無効化・削除できます。token を更新するときは、<strong>API Token</strong> フィールドを更新して保存してください。</p>',18)])])}const b=t(l,[["render",n]]);export{c as __pageData,b as default};
